<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { api, formatCost, formatNumber } from '../api.js';
import UsageChart from '../components/UsageChart.vue';
import UiIcon from '../components/UiIcon.vue';
const data = ref({ today: {}, totals: {}, series: [] }), keys = ref([]), loading = ref(true);
async function load() { const [overview, keyData] = await Promise.all([api('GET', '/api/admin/overview'), api('GET', '/api/admin/keys')]); data.value = overview; keys.value = keyData.keys; loading.value = false; }
onMounted(() => { load(); window.addEventListener('relay-refresh', load); });
onBeforeUnmount(() => window.removeEventListener('relay-refresh', load));
const average = computed(() => data.value.today.requests ? data.value.today.cost / data.value.today.requests : 0);
</script>
<template><div v-if="loading" class="panel skeleton-panel"></div><template v-else><section class="billing-summary"><article><span>累计 Token</span><strong>{{ formatNumber(data.totals.tokens) }}</strong><small>所有 API Key 的历史消耗</small></article><article><span>累计计费</span><strong>{{ formatCost(data.totals.cost) }}</strong><small>按模型输入与输出单价计算</small></article><article><span>今日计费</span><strong>{{ formatCost(data.today.cost) }}</strong><small>今日 {{ formatNumber(data.today.requests) }} 次请求</small></article><article><span>今日平均单次费用</span><strong>{{ formatCost(average) }}</strong><small>仅用于运营分析，非支付账单</small></article></section><section class="panel"><header class="panel-header"><div><h2>Token 消耗趋势</h2><p>最近 14 天全部供应商合计</p></div><span class="badge neutral">USD 计费</span></header><UsageChart :series="data.series" metric="tokens" /></section><section class="panel"><header class="panel-header"><div><h2>按 API Key 结算</h2><p>额度消耗与费用明细</p></div></header><div class="table-wrap"><table><thead><tr><th>名称</th><th>输入 + 输出 Token</th><th>累计费用</th><th>Token 额度</th><th>费用额度</th><th>状态</th></tr></thead><tbody><tr v-for="key in keys" :key="key.id"><td><div class="cell-with-icon"><UiIcon name="key" :size="16" /><strong>{{ key.name }}</strong></div></td><td>{{ formatNumber(key.used_tokens) }}</td><td class="cost-cell">{{ formatCost(key.used_cost) }}</td><td>{{ key.token_quota ? formatNumber(key.token_quota) : '不限' }}</td><td>{{ key.budget_quota ? formatCost(key.budget_quota) : '不限' }}</td><td><span class="badge" :class="key.enabled ? 'success' : 'neutral'">{{ key.enabled ? '正常' : '停发' }}</span></td></tr></tbody></table></div></section><div class="footnote"><UiIcon name="info" :size="15" />费用按实际 usage 计算；上游未返回 usage 时使用字符数估算。金额采用美元，单价在“供应商与模型”中配置。</div></template></template>
